const cfg = $('Config').first().json;
const cat = $('Fetch CISA KEV').first().json;
const db = $('DB kev_entries').all().map(i => i.json).filter(r => r && r.cve_id);
const watch = $('DB cve_watch').all().map(i => i.json).filter(r => r && r.cve_id);
const allow = cfg.VENDOR_ALLOWLIST.map(s => s.toLowerCase());
const byId = new Map((cat.vulnerabilities || []).map(v => [v.cveID, v]));
const inScope = (cat.vulnerabilities || []).filter(v => allow.some(a => `${v.vendorProject} ${v.product}`.toLowerCase().includes(a)));
const dbIds = new Set(db.map(r => r.cve_id));
const since = new Date(Date.now() - cfg.KEV_LOOKBACK_DAYS * 864e5).toISOString().slice(0, 10);
const missing = inScope.filter(v => v.dateAdded >= since && !dbIds.has(v.cveID)).map(v => v.cveID);
const notInCatalog = db.filter(r => !byId.has(r.cve_id)).map(r => r.cve_id);
const mismatches = [];
for (const r of db) {
  const v = byId.get(r.cve_id); if (!v) continue;
  const diff = [];
  if (v.vendorProject !== r.vendor) diff.push(`vendor ${r.vendor} vs ${v.vendorProject}`);
  if (v.product !== r.product) diff.push(`product ${r.product} vs ${v.product}`);
  if (v.dateAdded !== r.date_added) diff.push(`date_added ${r.date_added} vs ${v.dateAdded}`);
  if (v.dueDate !== r.due_date) diff.push(`due_date ${r.due_date} vs ${v.dueDate}`);
  if ((v.knownRansomwareCampaignUse || 'Unknown') !== r.ransomware) diff.push(`ransomware ${r.ransomware} vs ${v.knownRansomwareCampaignUse}`);
  if (diff.length) mismatches.push(`${r.cve_id}: ${diff.join('; ')}`);
}
const enriched = db.filter(r => r.cvss_score != null);
const ai = db.filter(r => r.ai_summary);
const aiWeak = ai.filter(r => { const t = `${r.vendor} ${r.product} ${r.vuln_name || ''}`.toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 3); return !t.some(w => r.ai_summary.toLowerCase().includes(w)); }).map(r => r.cve_id);
// sample for NVD / EPSS re-check: 12 most recent enriched KEV + 8 most recent watch
const pick = (arr, n) => arr.slice(0, n);
const sample = [...pick(enriched, 12).map(r => ({ cve_id: r.cve_id, src: 'kev', cvss: r.cvss_score, epss: r.epss_score })),
                ...pick(watch.filter(w => w.cvss_score != null), 8).map(r => ({ cve_id: r.cve_id, src: 'watch', cvss: r.cvss_score, epss: r.epss_score }))];
const report = {
  checked_at: new Date().toISOString(), catalog_version: cat.catalogVersion, catalog_total: cat.count, catalog_in_scope: inScope.length,
  db_rows: db.length, db_enriched: enriched.length, db_with_ai: ai.length,
  missing_recent_in_scope: missing, rows_not_in_catalog: notInCatalog, field_mismatches: mismatches.slice(0, 50), field_mismatch_count: mismatches.length,
  ai_summary_not_mentioning_product: aiWeak.slice(0, 20), ai_weak_count: aiWeak.length, sample };
return [{ json: report }];

const sample = $('Compare KEV').first().json.sample;
const nvd = $('NVD lookup').all().map(i => i.json);
const pickCvss = (m) => { for (const k of ['cvssMetricV40','cvssMetricV31','cvssMetricV30','cvssMetricV2']) { const a = m?.[k]; if (Array.isArray(a) && a.length) { const p = a.find(x => x.type === 'Primary') || a[0]; return p.cvssData?.baseScore; } } return null; };
const rows = sample.map((s, i) => { const v = nvd[i]?.vulnerabilities?.[0]?.cve; const live = v ? pickCvss(v.metrics) : null; return { ...s, nvd_cvss: live, nvd_ok: v ? (live === s.cvss) : null, nvd_err: nvd[i]?.error ? String(nvd[i].error.message || nvd[i].error).slice(0, 80) : (v ? null : 'no result') }; });
return [{ json: { rows, cves: sample.map(s => s.cve_id).join(',') } }];

const prev = $('Compare NVD').first().json.rows;
const e = $input.first().json; const map = new Map((e.data || []).map(d => [d.cve, Number(d.epss)]));
const rows = prev.map(r => { const live = map.has(r.cve_id) ? map.get(r.cve_id) : null; return { ...r, epss_live: live, epss_ok: live == null || r.epss == null ? null : Math.abs(live - Number(r.epss)) <= 0.05 }; });
return [{ json: { rows } }];

const k = $('Compare KEV').first().json;
const rows = $('Compare EPSS').first().json.rows;
const arts = $('Article items').all().map(i => i.json);
const checks = $('Check article links').all().map(i => i.json);
const links = arts.map((a, i) => { const c = checks[i] || {}; const st = c.statusCode ?? (c.error ? 'ERR' : null); return { source: a.source, title: String(a.title).slice(0, 70), status: st, ok: typeof st === 'number' && st < 400 }; });
const L = [];
L.push(`Threat-intel data verification – ${k.checked_at.slice(0, 16).replace('T', ' ')} UTC`);
L.push('');
L.push(`A. CISA KEV catalog (version ${k.catalog_version}, ${k.catalog_total} entries, ${k.catalog_in_scope} in our product scope)`);
L.push(`   Stored rows checked: ${k.db_rows} (most recently added; Supabase returns max 1000 per query). Enriched with CVSS: ${k.db_enriched}. With AI summary: ${k.db_with_ai}.`);
L.push(`   Recent in-scope KEV entries missing from our DB: ${k.missing_recent_in_scope.length}${k.missing_recent_in_scope.length ? ' -> ' + k.missing_recent_in_scope.join(', ') : ' (none)'}`);
L.push(`   Stored rows no longer in catalog: ${k.rows_not_in_catalog.length}${k.rows_not_in_catalog.length ? ' -> ' + k.rows_not_in_catalog.slice(0, 10).join(', ') : ' (none)'}`);
L.push(`   Field mismatches vendor/product/dates/ransomware: ${k.field_mismatch_count}`); for (const m of k.field_mismatches.slice(0, 10)) L.push(`     - ${m}`);
L.push('');
L.push(`B. CVSS re-check against live NVD (${rows.length} sampled: 12 KEV + 8 CVE Watch)`);
for (const r of rows) L.push(`   - ${r.cve_id} [${r.src}] stored ${r.cvss} / NVD ${r.nvd_cvss ?? 'n/a'} -> ${r.nvd_ok === null ? (r.nvd_err || 'n/a') : r.nvd_ok ? 'OK' : 'MISMATCH'}`);
L.push(`   Result: ${rows.filter(r => r.nvd_ok === true).length} match, ${rows.filter(r => r.nvd_ok === false).length} mismatch, ${rows.filter(r => r.nvd_ok === null).length} not comparable`);
L.push('');
L.push(`C. EPSS re-check against FIRST (tolerance 0.05; EPSS is recomputed daily so small drift is normal)`);
L.push(`   ${rows.filter(r => r.epss_ok === true).length} within tolerance, ${rows.filter(r => r.epss_ok === false).length} drifted more, ${rows.filter(r => r.epss_ok === null).length} not comparable`);
for (const r of rows.filter(r => r.epss_ok === false)) L.push(`     - ${r.cve_id} stored ${r.epss} / live ${r.epss_live}`);
L.push('');
L.push(`D. Article links (${links.length} most recent relevant articles, HTTP status)`);
for (const l of links) L.push(`   - ${l.ok ? 'OK ' : 'FAIL'} ${l.status} | ${l.source} | ${l.title}`);
L.push('');
L.push(`E. AI summary sanity (KEV): ${k.ai_weak_count} of ${k.db_with_ai} summaries do not mention the vendor/product/title words${k.ai_weak_count ? ' -> ' + k.ai_summary_not_mentioning_product.join(', ') : ''}`);
L.push('');
const fails = k.missing_recent_in_scope.length + k.field_mismatch_count + rows.filter(r => r.nvd_ok === false).length + links.filter(l => !l.ok).length;
L.push(fails ? `RESULT: ${fails} item(s) need a look (see above).` : 'RESULT: all checks passed.');
const note = L.join('\n');
return [{ json: { note, subject: `[Threat Intel] Data verification – ${fails ? fails + ' issue(s)' : 'all checks passed'}`, fails } }];
